// ---------------- traveller ----------------
ADukeTraveller::ADukeTraveller()
{
	PrimaryActorTick.bCanEverTick = true;
	GetCharacterMovement()->MaxWalkSpeed = 140.f;
	GetCharacterMovement()->bOrientRotationToMovement = true;
	// Placeholder body until a civilian character is assigned (set Mesh on a Blueprint subclass)
	static ConstructorHelpers::FObjectFinder<UStaticMesh> Cyl(TEXT("/Engine/BasicShapes/Cylinder.Cylinder"));
	UStaticMeshComponent* Body = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("PlaceholderBody"));
	Body->SetupAttachment(GetCapsuleComponent());
	if (Cyl.Succeeded()) Body->SetStaticMesh(Cyl.Object);
	Body->SetRelativeScale3D(FVector(0.5f, 0.5f, 1.75f));
	Body->SetCollisionEnabled(ECollisionEnabled::NoCollision);
}

void ADukeTraveller::Tick(float Dt)
{
	Super::Tick(Dt);
	const float Now = GetWorld()->GetTimeSeconds();
	if (TravState == EDukeTravellerState::Hostile)
	{
		if (AActor* T = ShootAt.Get())
		{
			SetActorRotation((T->GetActorLocation() - GetActorLocation()).GetSafeNormal2D().Rotation());
			if (Now > NextShot)
			{
				const FVector From = GetActorLocation() + FVector(0, 0, 50.f) + GetActorForwardVector() * 40.f;
				ADukeBlasterBolt::Fire(GetWorld(), this, From, FMath::VRandCone((T->GetActorLocation() - From).GetSafeNormal(), 0.05f), BlasterDamage, 7000.f, FLinearColor(0.2f, 0.4f, 1.f));
				NextShot = Now + FMath::FRandRange(0.6f, 1.1f);
			}
		}
		return;
	}
	if (TravState == EDukeTravellerState::Halted || TravState == EDukeTravellerState::PapersChecked) return;   // waits at the barrier
	const FVector To = (Goal - GetActorLocation()) * FVector(1, 1, 0);
	if (To.Size() > 40.f) AddMovementInput(To.GetSafeNormal(), 1.f);
}

void ADukeTraveller::DrawWeapon(AActor* Target) { TravState = EDukeTravellerState::Hostile; ShootAt = Target; GetCharacterMovement()->StopMovementImmediately(); }

// ---------------- checkpoint ----------------
ADukeCheckpoint::ADukeCheckpoint() { PrimaryActorTick.bCanEverTick = true; TravellerClass = ADukeTraveller::StaticClass(); }
void ADukeCheckpoint::BeginPlay() { Super::BeginPlay(); NextSpawn = GetWorld()->GetTimeSeconds() + 2.f; }

void ADukeCheckpoint::Tick(float Dt)
{
	Super::Tick(Dt);
	const float Now = GetWorld()->GetTimeSeconds();
	Queue.RemoveAll([](const TWeakObjectPtr<ADukeTraveller>& T) { return !T.IsValid(); });
	if (Now > NextSpawn && Queue.Num() < 4 && TravellerClass)
	{
		FActorSpawnParameters P; P.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AdjustIfPossibleButAlwaysSpawn;
		if (ADukeTraveller* T = GetWorld()->SpawnActor<ADukeTraveller>(TravellerClass, W(QueueStart) + FVector(0, 0, 100), FRotator::ZeroRotator, P))
		{
			T->bIsRebel = FMath::FRand() < RebelChance;
			T->bCarriesWeapons = T->bIsRebel ? FMath::FRand() < 0.7f : FMath::FRand() < ContrabandChance * 0.3f;
			T->bHasValidCredentials = !(FMath::FRand() < NoPapersChance) && !(T->bIsRebel && FMath::FRand() < 0.4f);
			Queue.Add(T);
		}
		NextSpawn = Now + SpawnEvery;
	}
	// queue up behind the barrier, 2.5 m apart
	for (int32 i = 0; i < Queue.Num(); ++i)
		if (ADukeTraveller* T = Queue[i].Get())
			if (T->TravState == EDukeTravellerState::Approaching) T->Goal = W(Barrier) + (W(QueueStart) - W(Barrier)).GetSafeNormal() * (120.f + 250.f * i);
}

// The gate guard's script for the traveller at the barrier. Returns the duty clip to play now.
FName ADukeCheckpoint::NextGateStep(ADukeTrooper* Guard, FVector& OutStandAt, AActor*& OutFace)
{
	const float Now = GetWorld()->GetTimeSeconds();
	OutStandAt = W(Barrier) + GetActorRightVector() * 150.f;
	ADukeTraveller* T = Current();
	OutFace = T;
	if (!T) return TEXT("patrol_look");
	if (FVector::Dist2D(T->GetActorLocation(), W(Barrier)) > 260.f && T->TravState == EDukeTravellerState::Approaching) return TEXT("checkpoint_halt");
	auto Next = [&](EDukeTravellerState S, float Secs) { T->TravState = S; StepUntil = Now + Secs; };
	switch (T->TravState)
	{
	case EDukeTravellerState::Approaching: Next(EDukeTravellerState::Halted, 2.f); return TEXT("checkpoint_halt");
	case EDukeTravellerState::Halted:
		if (Now < StepUntil) return TEXT("checkpoint_halt");
		if (T->bIsRebel && FMath::FRand() < 0.25f) { T->DrawWeapon(Guard); if (Squad.IsValid()) Squad->ReportThreat(Guard, T); return TEXT("checkpoint_halt"); }
		Next(EDukeTravellerState::PapersChecked, 4.f); return TEXT("check_credentials");
	case EDukeTravellerState::PapersChecked:
		if (Now < StepUntil) return TEXT("check_credentials");
		if (!T->bHasValidCredentials) { Next(EDukeTravellerState::Detained, 0.f); T->Goal = W(DetentionPoint); Queue.RemoveAt(0); return TEXT("command_point"); }
		Next(EDukeTravellerState::Searched, 4.f); return TEXT("inspect_freight");
	case EDukeTravellerState::Searched:
		if (Now < StepUntil) return TEXT("inspect_freight");
		if (T->bCarriesWeapons)
		{
			if (T->bIsRebel) { T->DrawWeapon(Guard); if (Squad.IsValid()) Squad->ReportThreat(Guard, T); Queue.RemoveAt(0); return TEXT("checkpoint_halt"); }
			Next(EDukeTravellerState::Detained, 0.f); T->Goal = W(DetentionPoint); Queue.RemoveAt(0); return TEXT("command_point");
		}
		Next(EDukeTravellerState::Cleared, 0.f); T->Goal = W(ExitPoint); T->SetLifeSpan(25.f); Queue.RemoveAt(0); return TEXT("command_advance");   // waved through
	default: return TEXT("patrol_look");
	}
}
